import logo from './logo.svg';
import './App.css';
import styles from './styles/InputStyles.module.css';

function App() {
  //return SubmitProblem();
  const [textValue, setTextValue] = useState('');
  const handleSubmit = (e) => {
    e.preventDefault();
    const formdata=new FormData(e.target);
    const descriptionText = formdata.get('description');
    if (descriptionText.trim() === '') {
      alert('题目描述不能为空');
    }else{
      console.log('题目描述：',descriptionText);
      alert('题目描述已提交:')
    }
  };
  return (
    <div className="App">
        <div>
          <h1>Submit Problem</h1>
        </div>
        <div>
          <label for="description">题目描述:</label>
          <form onSubmit = {handleSubmit}>
            <textarea rows="10" cols="50" id="description" name = "description" placeholder="在这里输入内容"></textarea>
            <button id="submitBtn" type="submit">提交</button>
          </form>

          {submittedValue && (
            <div style={{ whiteSpace: 'pre-wrap', marginTop: '20px' }}>
              提交的内容: {submittedValue}
            </div>
          )}
        </div>
    </div>
  );
}

export default App;
